//! 🧪️ Physical progress facts share strict neutral vectors and an independent Serde witness.
use super::*;
use semio_framework_value::{native_decoding::NativeDecodeRetirementRecipient,ErasedSnapshotRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneStep},retirement::{RetireOwned,admit_owned_retirement}};
fn io_grant()->RetainedCloneGrant{serde_json::from_value(serde_json::from_str::<serde_json::Value>(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()["retainedGrant"].clone()).unwrap()}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:3,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:2048}}
fn drain(owner:&mut dyn ErasedSnapshotRetirement){for _ in 0..100000{if matches!(owner.close_step(grant()).unwrap(),RetainedCloneStep::Complete(_))&&owner.terminal_is_empty(){return}}panic!("retained test owner did not close")}
fn retire<T:RetireOwned>(value:T){let(mut owner,_)=admit_owned_retirement(value,grant()).map_err(|(error,_)|error).unwrap();drain(owner.as_mut())}
#[test]
fn actual_progress_admission_preserves_shared_closed_facts_and_independent_serde(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧬️schema/🎯️dag-input/📊️progress/🧫️fixtures/🔣️.json")).unwrap();
    let live=std::cell::Cell::new(true);let mut observe=|_|live.get();let mut recipient=NativeDecodeRetirementRecipient::new();let mut accepted=0;let mut refused=0;
    for row in fixture["accepted"].as_array().unwrap(){let source=serde_json::to_string(row).unwrap();let mut control=NativeDecodeControl::new(1048576,&mut observe);control.install_retirement_recipient(&mut recipient).unwrap();let actual=decode_dag_computing_progress_json(&source,&mut control).unwrap();assert_eq!(serde_json::to_value(&actual).unwrap(),*row);let independent:DagComputingProgress=serde_json::from_str(&source).unwrap();assert_eq!(actual,independent);retire(actual);accepted+=1;}
    for row in fixture["refused"].as_array().unwrap(){let source=serde_json::to_string(row).unwrap();let mut control=NativeDecodeControl::new(1048576,&mut observe);control.install_retirement_recipient(&mut recipient).unwrap();assert!(decode_dag_computing_progress_json(&source,&mut control).is_err());drop(control);drain(&mut recipient);refused+=1;}
    for row in fixture["duplicate"].as_array().unwrap(){let mut control=NativeDecodeControl::new(1048576,&mut observe);control.install_retirement_recipient(&mut recipient).unwrap();assert!(decode_dag_computing_progress_json(row.as_str().unwrap(),&mut control).is_err());drop(control);drain(&mut recipient);}
    eprintln!("[DEBUG] actual Rust computing facts accepted={accepted} refused={refused} duplicate=1 independentSerde=true");
}
#[test]
fn retained_progress_grammar_keeps_one_cumulative_owner_across_zero_and_single_unit_grants(){
    use super::super::retained::{DagInputCursor,DagInputKind,DagInputFacts};
    let source="{\"active\":\"é雪\",\"stale\":[\"English / Deutsch\",\"old\"]}";let original=source.as_ptr();let mut cursor=DagInputCursor::new(DagInputKind::Progress);let live=std::cell::Cell::new(true);let mut receipt=None;let mut recipient=NativeDecodeRetirementRecipient::new();let mut previous_owned=0;let mut turns=0;
    loop{let mut observe=|_|live.get();let mut control=match receipt.take(){Some(receipt)=>NativeDecodeControl::resume(receipt,&mut observe).unwrap(),None=>NativeDecodeControl::new_retained(&mut observe)};let before=(cursor.position(),control.owned_bytes());assert!(!cursor.step(source,0,&mut control,io_grant()).unwrap());assert_eq!((cursor.position(),control.owned_bytes()),before);let demand=cursor.normal_step_demands(source).unwrap();for axis in 0..5{let mut denied=io_grant();let relevant=match axis{0=>{denied.maximum_items=0;true},1=>{denied.maximum_copy_bytes=0;demand.copy_bytes!=0},2=>{denied.maximum_capacity_bytes=0;demand.capacity_bytes!=0},3=>{denied.maximum_release_bytes=0;demand.release_bytes!=0},_=>{denied.maximum_depth=0;demand.depth!=0}};if relevant{assert!(!cursor.step(source,1,&mut control,denied).unwrap());assert_eq!(cursor.normal_step_progress(),Default::default());assert_eq!((cursor.position(),control.owned_bytes()),before);}}let complete=cursor.step(source,1,&mut control,io_grant()).unwrap();assert!(control.owned_bytes()>=previous_owned);previous_owned=control.owned_bytes();receipt=Some(control.pause().unwrap());turns+=1;assert!(turns<100000);if complete{break}}
    let DagInputFacts::Progress(facts)=cursor.facts().unwrap()else{panic!("wrong semantic fact")};assert_eq!(serde_json::to_value(facts).unwrap(),serde_json::from_str::<serde_json::Value>(source).unwrap());assert_eq!(source.as_ptr(),original);assert!(turns>1);retire(cursor);drain(&mut recipient);
    eprintln!("[DEBUG] retained Rust computing IO oneUnitGrants={turns} cumulativeOwned={previous_owned} zeroPreserves=true independentSerde=true originalsource=true");
}

#[test]
fn retained_typed_members_admit_all_original_dag_vectors_without_whole_collection_copy(){
    use super::super::retained::{DagInputCursor,DagInputKind,DagInputFacts};
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();let mut accepted=0;let mut refused=0;let mut grants=0;
    for(valid,name)in[(true,"accepted"),(false,"refused")]{for row in fixture[name].as_array().unwrap(){let kind=match row["kind"].as_str().unwrap(){"selection"=>DagInputKind::Selection,"channels"=>DagInputKind::Channels,"statuses"=>DagInputKind::Statuses,"hover"=>continue,_=>panic!("unknown declared kind")};let source=serde_json::to_string(&row["value"]).unwrap();let pointer=source.as_ptr();let mut cursor=DagInputCursor::new(kind);let mut receipt=None;let live=std::cell::Cell::new(true);let mut completed=false;let mut failed=false;let mut previous_owned=0;
        for _ in 0..100000{let mut observe=|_|live.get();let mut control=match receipt.take(){Some(receipt)=>NativeDecodeControl::resume(receipt,&mut observe).unwrap(),None=>NativeDecodeControl::new_retained(&mut observe)};let before=(cursor.position(),control.owned_bytes());assert!(!cursor.step(&source,0,&mut control,io_grant()).unwrap());assert_eq!((cursor.position(),control.owned_bytes()),before);let result=cursor.step(&source,1,&mut control,io_grant());if let Some(value)=cursor.take_retired_update(){retire(value)}assert!(control.owned_bytes()>=previous_owned);previous_owned=control.owned_bytes();receipt=Some(control.pause().unwrap());grants+=1;match result{Ok(true)=>{completed=true;break},Ok(false)=>assert!(cursor.facts().is_none()),Err(_)=>{failed=true;break}}}
        assert_eq!(completed,valid);assert_eq!(failed,!valid);if valid{let actual=match cursor.facts().unwrap(){DagInputFacts::Selection(value)=>serde_json::to_value(value).unwrap(),DagInputFacts::Channels(value)=>serde_json::to_value(value).unwrap(),DagInputFacts::Statuses(value)=>{let oracle:std::collections::BTreeMap<_,_>=value.iter().map(|(key,value)|(key.as_str(),value)).collect();serde_json::to_value(oracle).unwrap()},_=>panic!("wrong declared fact")};assert_eq!(actual,row["value"]);accepted+=1;}else{assert!(cursor.facts().is_none());refused+=1;}assert_eq!(source.as_ptr(),pointer);assert_eq!(serde_json::from_str::<serde_json::Value>(&source).unwrap(),row["value"]);retire(cursor);
    }}
    eprintln!("[DEBUG] retained typed original DAG members accepted={accepted} refused={refused} oneUnitGrants={grants} hiddenPartialFacts=true noWholeCollectionCopy=true independentSerde=true");
}
